# ---- inlined from core/wilson.py ----
"""Wilson score interval for a binomial proportion.

Windmill's eval UI shows a pass rate (passed / scored) as a bare point. With a
finite number of scored runs that point has real uncertainty, and the naive
normal approximation (phat +/- z*sqrt(phat*(1-phat)/n)) is badly behaved near 0
and 1 and can even leave [0, 1]. The Wilson interval stays inside [0, 1], is
asymmetric toward 0.5, and is well-behaved for small n, which is exactly the
regime an eval dataset lives in.
"""


import math
from dataclasses import dataclass

# z for a 95% two-sided interval. Kept explicit so callers can widen/narrow it.
Z_95 = 1.959963984540054


@dataclass(frozen=True)
class Interval:
    point: float  # observed proportion (passed / n)
    low: float
    high: float

    @property
    def half_width(self) -> float:
        return (self.high - self.low) / 2.0

    def __str__(self) -> str:  # pragma: no cover - display helper
        return f"{self.point:.1%} [{self.low:.1%}, {self.high:.1%}]"


def wilson_interval(successes: int, n: int, z: float = Z_95) -> Interval:
    """Wilson score interval for `successes` out of `n` trials.

    `point` is the plain observed proportion; `low`/`high` are the Wilson bounds,
    clamped to [0, 1]. For n == 0 the interval is the whole [0, 1] with an
    undefined point reported as 0.0, since nothing is known yet.
    """
    if successes < 0 or n < 0 or successes > n:
        raise ValueError(f"need 0 <= successes <= n, got successes={successes}, n={n}")
    if n == 0:
        return Interval(point=0.0, low=0.0, high=1.0)

    phat = successes / n
    z2 = z * z
    denom = 1.0 + z2 / n
    center = (phat + z2 / (2.0 * n)) / denom
    margin = (z * math.sqrt((phat * (1.0 - phat) + z2 / (4.0 * n)) / n)) / denom
    low = max(0.0, center - margin)
    high = min(1.0, center + margin)
    return Interval(point=phat, low=low, high=high)

# ---- inlined from core/resampling.py ----
"""Paired resampling for comparing two agent versions on the same cases.

Windmill runs an eval as a flow over a dataset and reports the pass-rate delta
between two agent versions as a raw subtraction. Because both versions are scored
on the *same* cases, the comparison is paired, and a raw delta says nothing about
whether it would survive re-running. Two tools here answer that:

- `paired_bootstrap_ci`: a confidence interval on the mean per-case delta, by
  resampling cases with replacement (captures between-case variability).
- `paired_permutation_test`: a p-value for "no difference", by randomly swapping
  the A/B label within each case (the exact null for a paired comparison).

Both take one pass rate per case per version (each typically the mean of N
repeated runs), keep the pairing, are seeded, and use only the stdlib.
"""


import random
from dataclasses import dataclass


def _mean(xs: list[float]) -> float:
    return sum(xs) / len(xs)


@dataclass(frozen=True)
class DeltaCI:
    delta: float  # mean(B) - mean(A) over cases
    low: float
    high: float


def _check_pairs(a: list[float], b: list[float]) -> None:
    if len(a) != len(b):
        raise ValueError(f"paired inputs must be equal length, got {len(a)} and {len(b)}")
    if not a:
        raise ValueError("need at least one case")


def _check_resampling(iters: int, alpha: float) -> None:
    if iters < 1:
        raise ValueError(f"iters must be at least 1, got {iters}")
    if not 0.0 < alpha < 1.0:
        raise ValueError(f"alpha must be in (0, 1), got {alpha}")


def paired_bootstrap_ci(
    rates_a: list[float],
    rates_b: list[float],
    iters: int = 10_000,
    seed: int = 0,
    alpha: float = 0.05,
) -> DeltaCI:
    """Percentile bootstrap CI on the mean per-case delta (B - A).

    Resamples the *cases* with replacement, keeping each case's (A, B) pair
    together so the pairing is preserved.
    """
    _check_pairs(rates_a, rates_b)
    _check_resampling(iters, alpha)
    n = len(rates_a)
    observed = _mean(rates_b) - _mean(rates_a)
    rng = random.Random(seed)
    deltas = []
    for _ in range(iters):
        idx = [rng.randrange(n) for _ in range(n)]
        da = sum(rates_a[i] for i in idx) / n
        db = sum(rates_b[i] for i in idx) / n
        deltas.append(db - da)
    deltas.sort()
    lo = deltas[int((alpha / 2.0) * iters)]
    hi = deltas[min(iters - 1, int((1.0 - alpha / 2.0) * iters))]
    return DeltaCI(delta=observed, low=lo, high=hi)


@dataclass(frozen=True)
class PermutationResult:
    delta: float
    p_value: float
    significant: bool

    def verdict(self, alpha: float = 0.05) -> str:  # pragma: no cover - display
        if self.p_value <= alpha:
            return f"significant (delta={self.delta:+.1%}, p={self.p_value:.3f})"
        return f"not distinguishable from noise (delta={self.delta:+.1%}, p={self.p_value:.3f})"


def paired_permutation_test(
    rates_a: list[float],
    rates_b: list[float],
    iters: int = 10_000,
    seed: int = 0,
    alpha: float = 0.05,
) -> PermutationResult:
    """Two-sided paired permutation test on the mean per-case delta.

    Under the null (the two versions are interchangeable) swapping A and B within
    a case is equally likely, so we flip each case's sign independently and count
    how often the permuted |mean delta| reaches the observed one. The observed
    assignment is included, so the p-value is never 0.
    """
    _check_pairs(rates_a, rates_b)
    if iters < 0:
        raise ValueError(f"iters must be >= 0, got {iters}")
    if not 0.0 < alpha < 1.0:
        raise ValueError(f"alpha must be in (0, 1), got {alpha}")
    n = len(rates_a)
    diffs = [b - a for a, b in zip(rates_a, rates_b)]
    observed = abs(sum(diffs) / n)
    rng = random.Random(seed)
    at_least_as_extreme = 1  # count the observed assignment itself
    for _ in range(iters):
        total = 0.0
        for d in diffs:
            total += d if rng.random() < 0.5 else -d
        if abs(total / n) >= observed - 1e-12:
            at_least_as_extreme += 1
    p_value = at_least_as_extreme / (iters + 1)
    delta = sum(diffs) / n
    return PermutationResult(delta=delta, p_value=p_value, significant=p_value <= alpha)

# ---- inlined from core/reliability.py ----
"""Turn repeated run outcomes into an auditable reliability report.

Input is the raw per-run pass/fail for two agent versions on the same cases,
each case run several times. Output is a plain data structure: per-case Wilson
intervals and a flakiness flag, and an overall pass rate per version with a
Wilson interval, plus a bootstrap CI and a permutation p-value on the delta.

The verdict is computed here, from the numbers, so it can be recomputed and
checked; nothing is taken on trust from a model.
"""


from dataclasses import dataclass, field


# A case's outcomes = the ordered pass/fail of each repeated run.
CaseOutcomes = dict[str, list[bool]]


@dataclass(frozen=True)
class CaseReport:
    case_id: str
    interval_a: Interval
    interval_b: Interval
    flaky_a: bool  # some but not all runs passed for version A
    flaky_b: bool


@dataclass(frozen=True)
class ReliabilityReport:
    version_a: str
    version_b: str
    runs_per_case: int
    overall_a: Interval
    overall_b: Interval
    delta_ci: DeltaCI
    test: PermutationResult
    cases: list[CaseReport] = field(default_factory=list)

    @property
    def flaky_cases(self) -> list[str]:
        return [c.case_id for c in self.cases if c.flaky_a or c.flaky_b]


def _is_flaky(outcomes: list[bool]) -> bool:
    return 0 < sum(outcomes) < len(outcomes)


def _aligned_case_ids(a: CaseOutcomes, b: CaseOutcomes) -> list[str]:
    if a.keys() != b.keys():
        only_a = sorted(a.keys() - b.keys())
        only_b = sorted(b.keys() - a.keys())
        raise ValueError(f"case ids differ between versions; only in A: {only_a}, only in B: {only_b}")
    if not a:
        raise ValueError("no cases")
    return sorted(a.keys())


def build_report(
    outcomes_a: CaseOutcomes,
    outcomes_b: CaseOutcomes,
    version_a: str = "A",
    version_b: str = "B",
    z: float = Z_95,
    iters: int = 10_000,
    seed: int = 0,
    alpha: float = 0.05,
) -> ReliabilityReport:
    """Build the full reliability report from repeated run outcomes.

    `outcomes_a`/`outcomes_b` map a case id to the list of pass/fail booleans
    from that case's repeated runs. Both versions must cover the same case ids.
    """
    case_ids = _aligned_case_ids(outcomes_a, outcomes_b)

    run_counts: set[int] = set()
    for cid in case_ids:
        la, lb = len(outcomes_a[cid]), len(outcomes_b[cid])
        if la == 0 or lb == 0:
            raise ValueError(f"case {cid} has no runs for one version")
        run_counts.add(la)
        run_counts.add(lb)
    if len(run_counts) != 1:
        raise ValueError(
            f"every case must have the same number of runs per version; saw {sorted(run_counts)}"
        )
    runs = run_counts.pop()

    cases: list[CaseReport] = []
    rates_a: list[float] = []
    rates_b: list[float] = []
    passes_a = trials_a = passes_b = trials_b = 0
    for cid in case_ids:
        oa, ob = outcomes_a[cid], outcomes_b[cid]
        ia = wilson_interval(sum(oa), len(oa), z)
        ib = wilson_interval(sum(ob), len(ob), z)
        cases.append(CaseReport(cid, ia, ib, _is_flaky(oa), _is_flaky(ob)))
        rates_a.append(sum(oa) / len(oa))
        rates_b.append(sum(ob) / len(ob))
        passes_a += sum(oa); trials_a += len(oa)
        passes_b += sum(ob); trials_b += len(ob)

    # Caveat: this overall interval pools all runs as if independent Bernoulli
    # trials, but repeated runs of the same case are correlated, so it is
    # narrower than the true uncertainty. It is a display summary; the delta CI
    # and p-value below use the paired, case-level resampling that avoids this.
    overall_a = wilson_interval(passes_a, trials_a, z)
    overall_b = wilson_interval(passes_b, trials_b, z)
    delta_ci = paired_bootstrap_ci(rates_a, rates_b, iters=iters, seed=seed, alpha=alpha)
    test = paired_permutation_test(rates_a, rates_b, iters=iters, seed=seed, alpha=alpha)

    return ReliabilityReport(
        version_a=version_a,
        version_b=version_b,
        runs_per_case=runs,
        overall_a=overall_a,
        overall_b=overall_b,
        delta_ci=delta_ci,
        test=test,
        cases=cases,
    )

# ---- entrypoint from windmill/delta_reliability.py ----
def _as_bool(x: object) -> bool:
    """Coerce a JSON run outcome to bool, rejecting anything ambiguous.

    A dataset column may arrive as the string "false" or "0"; `bool("false")` is
    True, which would silently count a failure as a pass and corrupt every number
    downstream. Accept only genuine booleans or the ints 0/1.
    """
    if isinstance(x, bool):
        return x
    if isinstance(x, int) and x in (0, 1):
        return bool(x)
    raise ValueError(f"run outcome must be a boolean (or 0/1), got {x!r}")


def _coerce_outcomes(outcomes: object, name: str) -> dict:
    if not isinstance(outcomes, dict):
        raise ValueError(f"{name} must be a dict of case_id -> list, got {type(outcomes).__name__}")
    coerced = {}
    for cid, runs in outcomes.items():
        if not isinstance(runs, list):
            raise ValueError(f"{name}[{cid!r}] must be a list of run outcomes, got {type(runs).__name__}")
        coerced[cid] = [_as_bool(x) for x in runs]
    return coerced


def _report_to_dict(rep: ReliabilityReport) -> dict:
    return {
        "versions": {"a": rep.version_a, "b": rep.version_b},
        "runs_per_case": rep.runs_per_case,
        "overall": {
            "a": {"pass_rate": rep.overall_a.point, "ci": [rep.overall_a.low, rep.overall_a.high]},
            "b": {"pass_rate": rep.overall_b.point, "ci": [rep.overall_b.low, rep.overall_b.high]},
        },
        "delta": {
            "value": rep.delta_ci.delta,
            "ci": [rep.delta_ci.low, rep.delta_ci.high],
            "p_value": rep.test.p_value,
            "significant": rep.test.significant,
        },
        "flaky_cases": rep.flaky_cases,
        "cases": [
            {
                "case_id": c.case_id,
                "a": {"pass_rate": c.interval_a.point, "ci": [c.interval_a.low, c.interval_a.high]},
                "b": {"pass_rate": c.interval_b.point, "ci": [c.interval_b.low, c.interval_b.high]},
                "flaky": c.flaky_a or c.flaky_b,
            }
            for c in rep.cases
        ],
    }


def main(
    outcomes_a: dict,
    outcomes_b: dict,
    version_a: str = "A",
    version_b: str = "B",
    iters: int = 10_000,
    seed: int = 0,
    alpha: float = 0.05,
) -> dict:
    """Windmill entrypoint. `outcomes_a`/`outcomes_b`: {case_id: [true/false, ...]}."""
    rep = build_report(
        _coerce_outcomes(outcomes_a, "outcomes_a"),
        _coerce_outcomes(outcomes_b, "outcomes_b"),
        version_a=version_a,
        version_b=version_b,
        iters=iters,
        seed=seed,
        alpha=alpha,
    )
    return _report_to_dict(rep)


def _render(result: dict) -> str:
    d = result["delta"]
    verdict = "SIGNIFICANT" if d["significant"] else "not distinguishable from noise"
    lines = [
        f"{result['versions']['a']} vs {result['versions']['b']}"
        f"  ({result['runs_per_case']} runs/case)",
        f"  {result['versions']['a']}: {result['overall']['a']['pass_rate']:.1%}"
        f"  {result['versions']['b']}: {result['overall']['b']['pass_rate']:.1%}",
        f"  delta {d['value']:+.1%}  95% CI [{d['ci'][0]:+.1%}, {d['ci'][1]:+.1%}]"
        f"  p={d['p_value']:.3f}  -> {verdict}",
        f"  flaky cases: {result['flaky_cases'] or 'none'}",
    ]
    return "\n".join(lines)


if __name__ == "__main__":
    a = {"c1": [True, True, False], "c2": [False, False, True]}
    b = {"c1": [True, True, True], "c2": [True, False, True]}
    print(_render(main(a, b, "v1", "v2")))
